#include "fmod.hpp"
#include <cmath>

class Audio3DSystem {
    FMOD::System* system;
    FMOD::ChannelGroup* masterGroup;
    FMOD::Sound* gunshotSound;

public:
    bool init() {
        FMOD::System_Create(&system);
        system->init(512, FMOD_INIT_NORMAL, nullptr);
        system->createSound("gunshot.wav", FMOD_3D | FMOD_LOOP_OFF, nullptr, &gunshotSound);
        system->createChannelGroup("master", &masterGroup);
        return true;
    }

    void playGunshotAt(const Vector3& position, const Vector3& velocity) {
        FMOD::Channel* channel;
        system->playSound(gunshotSound, masterGroup, false, &channel);

        // Set 3D attributes
        FMOD_VECTOR pos = {position.x, position.y, position.z};
        FMOD_VECTOR vel = {velocity.x, velocity.y, velocity.z};
        channel->set3DAttributes(&pos, &vel);

        // Set minimum/maximum distance for attenuation
        channel->set3DMinMaxDistance(1.0f, 10000.0f);
    }

    void update(const Vector3& listenerPos, const Vector3& listenerForward,
                const Vector3& listenerUp, const Vector3& listenerVel) {
        FMOD_VECTOR pos = {listenerPos.x, listenerPos.y, listenerPos.z};
        FMOD_VECTOR fwd = {listenerForward.x, listenerForward.y, listenerForward.z};
        FMOD_VECTOR up = {listenerUp.x, listenerUp.y, listenerUp.z};
        FMOD_VECTOR vel = {listenerVel.x, listenerVel.y, listenerVel.z};

        system->set3DListenerAttributes(0, &pos, &vel, &fwd, &up);
        system->update();
    }

    void setOcclusion(FMOD::Channel* channel, float occlusionFactor) {
        // Low-pass filter when sound is behind walls
        float cutoff = 20000.0f * (1.0f - occlusionFactor);
        channel->setLowPassGain(occlusionFactor);
    }
};

// Wwise uses States and RTPCs to control music
// Here's the Unity C# integration:

using UnityEngine;
using System.Collections;

public class AdaptiveMusicManager : MonoBehaviour
{
    [Header("Music Parameters")]
    public float combatIntensity = 0f;  // 0 = calm, 1 = intense
    public bool isInExploration = true;
    public bool isInCombat = false;
    public bool isInBossFight = false;

    [Header("Wwise Events")]
    public AK.Wwise.Event musicPlayEvent;
    public AK.Wwise.Event musicStopEvent;

    // Wwise State Groups
    public AK.Wwise.State explorationState;
    public AK.Wwise.State combatState;
    public AK.Wwise.State bossState;

    void Start()
    {
        musicPlayEvent.Post(gameObject);

        // Start in exploration
        explorationState.SetValue();

        // Set initial intensity
        AkSoundEngine.SetRTPCValue("MusicIntensity", 0f);
    }

    void Update()
    {
        // Check game state and switch music
        if (isInBossFight)
        {
            bossState.SetValue();
            AkSoundEngine.SetRTPCValue("MusicIntensity", 1f);
        }
        else if (isInCombat)
        {
            combatState.SetValue();
            AkSoundEngine.SetRTPCValue("MusicIntensity", combatIntensity);
        }
        else
        {
            explorationState.SetValue();
            // Gradual fade down intensity
            combatIntensity = Mathf.Lerp(combatIntensity, 0f, Time.deltaTime * 2f);
            AkSoundEngine.SetRTPCValue("MusicIntensity", combatIntensity);
        }
    }

    // Called by enemy detection
    public void OnCombatStarted(float intensity)
    {
        isInCombat = true;
        combatIntensity = intensity;

        // Trigger combat sting
        AkSoundEngine.PostEvent("Combat_Stinger", gameObject);
    }

    public void OnCombatEnded()
    {
        isInCombat = false;

        // Play resolution sting
        AkSoundEngine.PostEvent("Combat_Resolved", gameObject);
    }

    void OnDestroy()
    {
        musicStopEvent.Post(gameObject);
    }
}

#include <vector>
#include <cmath>
#include <fstream>
#include <iostream>

struct WavHeader {
    char riff[4] = {'R', 'I', 'F', 'F'};
    int fileSize;
    char wave[4] = {'W', 'A', 'V', 'E'};
    char fmt[4] = {'f', 'm', 't', ' '};
    int fmtSize = 16;
    short audioFormat = 1;
    short numChannels = 1;
    int sampleRate = 44100;
    int byteRate;
    short blockAlign;
    short bitsPerSample = 16;
    char data[4] = {'d', 'a', 't', 'a'};
    int dataSize;
};

// Synthesize a gunshot sound procedurally
std::vector<short> synthesizeGunshot(float duration = 0.5f) {
    int sampleRate = 44100;
    int numSamples = (int)(duration * sampleRate);
    std::vector<short> samples(numSamples);

    for (int i = 0; i < numSamples; ++i) {
        float t = (float)i / sampleRate;
        float envelope;

        // Attack: very fast pop
        if (t < 0.01f) {
            envelope = t / 0.01f;
        }
        // Decay: quick fade
        else {
            envelope = exp(-t * 20.0f);
        }

        // Noise burst (white noise through envelope)
        float noise = ((float)rand() / RAND_MAX) * 2.0f - 1.0f;

        // Low-pass filter to make it sound like a gun (not static)
        static float lastSample = 0;
        float filtered = lastSample + 0.3f * (noise - lastSample);
        lastSample = filtered;

        // Add some low-frequency thump
        float thump = sin(80.0f * 3.14159f * 2.0f * t) * exp(-t * 15.0f);

        float sample = (filtered * 0.7f + thump * 0.3f) * envelope * 0.8f;
        samples[i] = (short)(sample * 32767);
    }

    return samples;
}

void saveWav(const std::string& filename, const std::vector<short>& samples, int sampleRate) {
    WavHeader header;
    header.dataSize = samples.size() * sizeof(short);
    header.fileSize = sizeof(WavHeader) - 8 + header.dataSize;
    header.byteRate = sampleRate * sizeof(short);
    header.blockAlign = sizeof(short);

    std::ofstream file(filename, std::ios::binary);
    file.write((char*)&header, sizeof(header));
    file.write((char*)samples.data(), header.dataSize);
}

int main() {
    auto gunshot = synthesizeGunshot(0.5f);
    saveWav("gunshot.wav", gunshot, 44100);
    std::cout << "Generated gunshot.wav from pure code!\n";
    return 0;
}
